/* 0x58e6a0, shows one goods slot of the production window's grids in the part form of the view: an empty slot
   (good 0) loses its objects; else it gets its stock bar, its icon (an input icon taking the amount when input is
   set, its style 0xca with the permission 0x200, else 0x8a; else a plain picture), the side's label (side bit 1:
   0x747 and the buy price at 0.9 of gm_GoodsPrice, bit 2: 0x746 and the sell price: the market (class 0xa) 1.1
   times it, else the building's priceFactor; a building of kind 0x47 prices by its player slot), the progress
   of the building's running job of the goods (job 4 / 3) as the icon's fill, the icon's and the bar's values
   (the input clamped to the amount, without the permission less the reserved part), the tooltip "%s~ %li %s"
   (name, amount, unit) and the positions of all its objects in the window
   @deep rewritten against the original (was a condensed draft, 1649 B; now 1931 vs 1936, 637 vs 638 instructions, same
   calls, no ref differences): the empty slot's clean-up, the stock bar, the icon (input icon style 0xca /
   0x8a or a picture), the side labels 0x747 / 0x746, the sell price (kind 0x47 by its player slot, the
   market class 0xa * 1.1, else * priceFactor) and the buy price (* 0.9) through one gm_FormatAmount each,
   the job progress fill (job 4 / 3), the input clamp and the bar values, the tooltip '%s~ %li %s', the
   moves. The slot type is LCPRODSLOT (fields named), AIBLD gets priceFactor / playerSlot in this unit's
   view, d2_CreateWinText's 16-bit call goes through d2_CreateWinTextS. All code hunks read: allocation and
   scheduling - the d2_Objs base loaded before or after the index arithmetic (0x58ec03 '- lea
   edx,[eax+eax*2]... mov ecx,[d2_Objs]' / '+ mov edx,[d2_Objs] ... lea eax'), the bar's stock loaded into
   edi before d2_GetObjValue (0x58eb84 '+ mov edi, [esi+0x34]'), the argument loads of the sprintf
   (0x58ec5f) and of the moves in another register order (0x58ed57: the aligner pairs the slider move with
   the buy-price move). */
void ai_ShowProdSlot(int view, int part, LCPRODSLOT *slot, int input, unsigned char side, AIBLD *bld)
{
    D2WIN *win;
    AIJOB *job;
    AIBTYPE *bt;
    int style;
    int value;
    int max;
    char text[0x20];

    d2_SetForm(view, part);
    win = &d2_Wins[d2_Views[view].wins[part]];
    if (slot->good != 0) {
        if (slot->slider == -1)
            slot->slider = d2_WinOpenSlider(slot->x + 6, slot->y, 0x30, 0, 0x64, 0x6a, 0x3d, d2_LastWindow);
        if (slot->check == -1) {
            if (input) {
                style = 0x8a;
                if ((ai_BuildingPerms & 0x200) != 0)
                    style = 0xca;
                slot->check = d2_WinOpenInputIcon(slot->x + 0xf, slot->y + 6, slot->good + 0xdf, style, d2_LastWindow);
                d2_SetObjFont(slot->check, 0x54);
            } else {
                slot->check = d2_WinOpenPic(slot->x + 0xf, slot->y + 6, slot->good + 0xdf, d2_LastWindow);
                d2_Objs[slot->check].interactive = 1;
            }
        }
        if (slot->label == -1) {
            if (side & 1)
                slot->label = d2_WinOpenPic(slot->x + 0xf, slot->y + 0x3a, 0x747, d2_LastWindow);
            else if (side & 2)
                slot->label = d2_WinOpenPic(slot->x + 0xf, slot->y + 0x3a, 0x746, d2_LastWindow);
        }
        if (side & 2) {
            bt = &((AIBTYPE *)ai_BTypes)[bld->kind];
            gm_FormatAmount((int)(bld->kind == 0x47 ? gm_GoodsPrice(slot->good, (unsigned char)bld->playerSlot)
                                  : bt->buildingClass == 0xa
                                      ? gm_GoodsPrice(slot->good, ai_OwnPlayer) * 1.1
                                      : gm_GoodsPrice(slot->good, ai_OwnPlayer) * bld->priceFactor),
                            ai_OwnPlayer, text);
            if (slot->priceText == -1)
                slot->priceText = d2_CreateWinTextS(slot->x + 0x10, slot->y + 0x40, text, d2_LastWindow);
            else
                d2_SetObjText(slot->priceText, text);
            d2_Objs[slot->priceText].w = 0x2d;
            d2_Objs[slot->priceText].font = 0x54;
            d2_Objs[slot->priceText].rightAligned = 1;
        }
        if (side & 1) {
            gm_FormatAmount((int)(bld->kind == 0x47 ? gm_GoodsPrice(slot->good, (unsigned char)bld->playerSlot)
                                                    : gm_GoodsPrice(slot->good, ai_OwnPlayer) * 0.9),
                            ai_OwnPlayer, text);
            if (slot->buyPriceText == -1)
                slot->buyPriceText = d2_CreateWinTextS(slot->x + 0x10, slot->y + 0x49, text, d2_LastWindow);
            else
                d2_SetObjText(slot->buyPriceText, text);
            d2_Objs[slot->buyPriceText].w = 0x2d;
            d2_Objs[slot->buyPriceText].font = 0x54;
            d2_Objs[slot->buyPriceText].rightAligned = 1;
        }
        for (job = (AIJOB *)he_FindEvent(2, 0, 4, 3, bld->id); job != 0; job = (AIJOB *)he_NextEvent())
            if (job->u.w.lo == slot->good)
                break;
        if (job == 0)
            for (job = (AIJOB *)he_FindEvent(2, 0, 3, 3, bld->id); job != 0; job = (AIJOB *)he_NextEvent())
                if (job->u.w.lo == slot->good)
                    break;
        if (job == 0 || (job->words14[0] == 0 && job->words14[1] == 0)) {
            if (slot->check != -1)
                d2_Objs[slot->check].fillFraction = 0;
        } else if (job->kind == 4) {
            d2_Objs[slot->check].fillFraction = (float)(1.0 - job->prodLeft / job->prodWork);
        } else if (job->kind == 3) {
            d2_Objs[slot->check].fillFraction = (float)(1.0 - job->incomeAmount / job->incomeAmountF);
        }
        if (input) {
            value = d2_GetObjValue(slot->check);
            if (value > slot->amount)
                value = slot->amount;
            max = slot->amount;
            if ((ai_BuildingPerms & 0x200) == 0)
                max -= slot->reserved;
            d2_SetObjValue(slot->check, 0, max < 0 ? 0 : max, value);
            if (slot->amount != 0)
                d2_Objs[slot->check].greyed = 0;
            else
                d2_Objs[slot->check].greyed = 1;
            value = d2_GetObjValue(slot->check);
            d2_SetObjValue(slot->slider, 0, slot->stock, slot->amount - (value < 0 ? 0 : value), slot->reserved);
        } else {
            if (slot->amount != 0)
                d2_Objs[slot->check].greyed = 0;
            else
                d2_Objs[slot->check].greyed = 1;
            d2_SetObjValue(slot->slider, 0, slot->stock, slot->amount, slot->reserved);
        }
        d2_Objs[slot->check].style = 0x22;
        d2_Objs[slot->check].captionX = 4;
        d2_Objs[slot->check].captionY = 0;
        sprintf(d2_Objs[slot->check].caption, "%s~ %li %s", txt_ObjectNames[slot->good][0], slot->amount, txt_Ptrs[0x3fe8]);
        if (slot->check >= 0)
            d2_MoveObj(win->x + slot->x + 0xf, win->y + slot->y + 6, slot->check);
        if (slot->label >= 0)
            d2_MoveObj(win->x + slot->x + 0xf, win->y + slot->y + 0x3a, slot->label);
        if (slot->priceText >= 0)
            d2_MoveObj(win->x + slot->x + 0x12, win->y + slot->y + 0x3f, slot->priceText);
        if (slot->buyPriceText >= 0)
            d2_MoveObj(win->x + slot->x + 0x12, win->y + slot->y + 0x49, slot->buyPriceText);
        if (slot->slider >= 0)
            d2_MoveObj(win->x + slot->x + 6, win->y + slot->y, slot->slider);
        if (slot->win >= 0)
            d2_MoveObj(win->x + slot->x + 0xf, win->y + slot->y + 6, d2_Wins[slot->win].parent);
    } else {
        if (slot->check != -1) {
            d2_RemoveObj(slot->check);
            slot->check = -1;
        }
        if (slot->label != -1) {
            d2_RemoveObj(slot->label);
            slot->label = -1;
        }
        if (slot->priceText != -1) {
            d2_RemoveObj(slot->priceText);
            slot->priceText = -1;
        }
        if (slot->buyPriceText != -1) {
            d2_RemoveObj(slot->buyPriceText);
            slot->buyPriceText = -1;
        }
        if (slot->slider != -1) {
            d2_RemoveObj(slot->slider);
            slot->slider = -1;
        }
        if (slot->win != -1) {
            d2_RemoveWindow(slot->win);
            slot->win = -1;
        }
    }
}

char * gm_FindGoods(int p, unsigned id);

/* 0x58ee30, the reverse direction table and entry fill (1117 B, ROUGH): the 68-dword kind table (entry i = the
   label, 2 / 3 / 4) selected by the byte +0x1c of param_2 fills the column titles 0x6f4f0c; the goods of the
   character 0x4ffe90 (param_2 + 10, 1, 5) / 0x4ffcc0 fill the rows 0x6f4f60: an existing id refreshes +0x30
   (0x50aaf0), a new row is created only when the record param_2[0] is not 0x1db / 0x1dc or the object
   0x4ffc40 (param_1 + 0x65, the goods) has a non-zero +4; the second pass 0x6f4f90 refreshes the amounts
   (0x50aaf0 / 0x50ab50, +0x2c = the amount * the count / 4) for the other kinds, and with 0x6f231c & 0x200 and
   0x1467398 the clicked entry 0x5fe710 cycles its state +0x1c (0x4c3ba0 / 0x4c3d90 / 0x4c49e0); the text check
   0x475980 (window +0x18 == 0x41) gives the return 1
   @deep B: 445 code hunks; ROUGH reverse direction table. The 68-dword kind table looked like 0x58e130's (the original has sub esp,0x114 + stack init stores of 2 / 3 / 4), and it is an automatic int tbl[68] (the original fills it on the stack at 0x58ee51.., register stores; a static one has no counterpart in the exe's data and cannot be linked), although that form has more hunks (470 vs 445). No other meaning error found; the row fill / second pass / click cycle are all present, the difference is code shape */
int ai_UpdateStoreGoods(int param_1, short *param_2)
{
    int tbl[68] = {
        2, 0, 0, 0, 2, 0, 0, 0, 2, 0, 0, 0, 3, 0, 0, 0,
        4, 0, 0, 0, 3, 2, 0, 0, 4, 3, 2, 0, 4, 3, 3, 0,
        4, 4, 0, 0, 4, 0, 2, 0, 4, 3, 3, 0, 4, 4, 3, 0,
        4, 4, 4, 0, 4, 4, 3, 0, 4, 4, 3, 3, 4, 4, 4, 3,
        4, 4, 4, 4
    };
    int *p;
    unsigned short *g;
    int *q;
    int i;
    int n;
    int st;

    i = 0;
    for (p = (int *)(unsigned)((char *)ai_ProdRows + 0xc); p < (int *)(unsigned)((unsigned)((char *)ai_ProdRows + 0x5c)); p += 5, i++)
        *p = tbl[i + ((unsigned char *)param_2)[0x1c] * 4];
    g = (unsigned short *)gm_Query(U_I((char *)param_2 + 10), 1, 5);
    while (g != 0) {
        n = 0;
        for (p = (int *)(unsigned)&ai_ProdGoods; p < (int *)(unsigned)((unsigned)((char *)ai_ProdGoods + 0x380)); p += 0xe, n++) {
            if (*p == *g) {
                if (n < 0x10)
                    *(int *)((unsigned)((char *)ai_ProdGoods + 0x30) + n * 0x38) = gm_ListAmount((int)param_2, g);
                break;
            }
            if (*p == 0) {
                q = (int *)gm_FindGoods(U_I(param_1 + 0x65), *g);
                if (n < 0x10 && ((*param_2 != 0x1db && *param_2 != 0x1dc) || q == 0 || q[1] != 0)) {
                    *(int *)((unsigned)((char *)ai_ProdGoods + 0x2c) + n * 0x38) = 0;
                    *(int *)((unsigned)&ai_ProdGoods + n * 0x38) = *g;
                    *(int *)((unsigned)((char *)ai_ProdGoods + 0x30) + n * 0x38) = 0;
                    *(int *)((unsigned)((char *)ai_ProdGoods + 0x34) + n * 0x38) = 0;
                }
                break;
            }
        }
        g = (unsigned short *)gm_QueryNext();
    }
    for (q = (int *)(unsigned)((char *)ai_ProdGoods + 0x30); q < (int *)(unsigned)((unsigned)((char *)ai_ProdGoods + 0x3b0)); q += 0xe) {
        g = (unsigned short *)gm_Query(U_I((char *)param_2 + 10), 1, 0, q[-0xc]);
        if (g == 0) {
            q[-0xc] = 0;
            continue;
        }
        if (*param_2 == 0x1db || *param_2 == 0x1dc) {
            n = gm_FindGoods(U_I(param_1 + 0x65), *g);
            if (n != 0 && U_I(n + 4) != 0) {
                q[0] = gm_ListAmount((int)param_2, g);
                q[1] = gm_ListStock((int)param_2, *g);
            }
        } else {
            q[-1] = (gm_ListStock((int)param_2, *g) * U_I((char *)g + 0xe * 2)) >> 2;
            q[0] = gm_ListAmount((int)param_2, g);
            q[1] = gm_ListStock((int)param_2, *g);
        }
    }
    if ((U_I((unsigned)&ai_BuildingPerms) & 0x200) != 0 && U_I(((unsigned)&dm_L + 0x18)) != 0 && d2_CountPointerItems() == 0) {
        for (p = (int *)(unsigned)((char *)ai_ProdGoods + 0x20); p < (int *)(unsigned)((unsigned)((char *)ai_ProdGoods + 0x3a0)); p += 0xe) {
            if (*p == -1 || *p != U_I((unsigned)&d2_PointerObj))
                continue;
            n = gm_Query(U_I((char *)param_2 + 10), 1, 0, p[-8]);
            if (n == 0)
                break;
            st = U_I(n + 0x1c) < 4 ? U_I(n + 0x1c) + 1 : 0;
            cm_BeginFieldBlock(n, U_I(n + 2));
            cm_AddFieldValue(4, 1, (n - U_I((unsigned)&cm_FieldObject)) + 0x1c, &st);
            cm_SendFieldValues();
            U_I(n + 0x1c) = st;
        }
    }
    i = 0;
    for (p = (int *)(unsigned)((char *)ai_ProdGoods + 0x10); p <= (int *)(unsigned)((unsigned)((char *)ai_ProdGoods + 0x38f)); p += 0xe) {
        n = *p;
        if (n != -1 && U_I(U_I((unsigned)&d2_Objs) + 0x18 + n * 0x2ec) == 0x41 && d2_GetObjValue(n) != 0) {
            i = 1;
            break;
        }
    }
    return i;
}
/* 0x58f290, lays out the first goods grid (ai_ProdRows / ai_ProdGoods) of the transport / storage / equip windows
   in the part form of the view, as ai_LayoutProdGoodsList does for the production window but with the rows
   (the picture 0x743's height + 0x23) apart and the slots' side by the object obj: 0x1db (1), 0x1dc (2), else 3;
   with pointer set it puts the checked goods of both grids on the mouse pointer */
void ai_LayoutStoreGoods(int view, int part, int pointer, AIBLD *bld, unsigned short *obj)
{
    D2WIN *win;
    int width;
    int i;
    int k;
    int row;
    int n;

    win = &d2_Wins[d2_Views[view].wins[part]];
    width = win->w;
    d2_SetForm(view, part);
    for (i = 0; i < 4; i++)
        if (ai_ProdRows[i].title == -1)
            ai_ProdRows[i].title = d2_WinOpenPic(0, 0, 0x743, d2_LastWindow);
    for (i = 0; i < 4; i++) {
        if (ai_ProdRows[i].shown != ai_ProdRows[i].slots)
            d2_SetObjPic(ai_ProdRows[i].title, ai_ProdRows[i].slots + 0x741);
        ai_ProdRows[i].shown = ai_ProdRows[i].slots;
        if (ai_ProdRows[i].slots >= 2) {
            ai_ProdRows[i].x = (width - d2_Pics[ai_ProdRows[i].slots + 0x741].w) >> 1;
            ai_ProdRows[i].y = (d2_Pics[0x743].h + 0x23) * i;
        }
    }
    d2_SetForm(view, part);
    for (i = 0; i < 4; i++) {
        if (ai_ProdRows[i].shown >= 2) {
            d2_Objs[ai_ProdRows[i].title].disabled = 0;
            d2_MoveObj(ai_ProdRows[i].x + win->x, ai_ProdRows[i].y + win->y, ai_ProdRows[i].title);
        } else {
            d2_Objs[ai_ProdRows[i].title].disabled = 1;
        }
    }
    n = 0;
    row = 0;
    for (k = 0; k < 16; k++) {
        if (++n > ai_ProdRows[row].shown) {
            n = 1;
            do
                row++;
            while (ai_ProdRows[row].shown < 1);
        }
        ai_ProdGoods[k].x = ai_ProdRows[row].x + n * 0x44 - 0x44;
        ai_ProdGoods[k].y = ai_ProdRows[row].y;
        if (*obj == 0x1db)
            ai_ShowProdSlot(view, part, &ai_ProdGoods[k], pointer, 1, bld);
        else if (*obj == 0x1dc)
            ai_ShowProdSlot(view, part, &ai_ProdGoods[k], pointer, 2, bld);
        else
            ai_ShowProdSlot(view, part, &ai_ProdGoods[k], pointer, 3, bld);
    }
    if (pointer) {
        d2_ClearPointerItems();
        for (k = 0; k < 16; k++)
            if (ai_ProdGoods[k].check != -1)
                d2_SetPointerItem(ai_ProdGoods[k].good + 0xdf, d2_GetObjValue(ai_ProdGoods[k].check));
        for (k = 0; k < 8; k++)
            if (ai_ProdGoods2[k].check != -1)
                d2_SetPointerItem(ai_ProdGoods2[k].good + 0xdf, d2_GetObjValue(ai_ProdGoods2[k].check));
    }
}


