                            if (bankRows[i].icon != -1)
                                d2_SetObjValue(bankRows[i].icon, 0, 0, 0);
                            if (ownRows[i].icon != -1)
                                d2_SetObjValue(ownRows[i].icon, 0, 0, 0);
