    if (param_2[0x87] == owner)
        *(short *)((char *)&cfg[7] + 2) = *(short *)owner;
    cfg[1] = 0x400;
    cfg[2] = U_I(((unsigned)&gypsyFilter));
    cfg[3] = U_I(((unsigned)&gypsyFilter + 4));
    cfg[4] = 6;
    cfg[5] = 3;
