            return 0x20;
        for (i = 0; i < 0x3e; i++)
            rec[i] = 0;
        handle = *(int *)(param_1 + 4);
        *(char *)((char *)rec + 4) = 0x18;
        *(int *)((char *)rec + 8) = handle;
        *(int *)((char *)rec + 0xc) = handle;
        *(AITIME *)((char *)rec + 0x28) = ai_Time;
        *(char *)((char *)rec + 0x36) = 2;
        cm_SendMoneyDelta(handle, 0xfffffffc);
