{
    unsigned int f;
    int mask;

    f = ch->ailments;
    if (f != 0) {
        mask = 0;
        if (f & 0xf)
            mask = 7;
        else if (f & 0xf0)
            mask = 0x30;
        else if (f & 0xf00)
            mask = 0x300;
        else if (f & 0x3000)
            mask = 0x1000;
        else if (f & 0x1c000)
            mask = 0xc000;
        else if (f & 0xe0000)
            mask = 0x20000;
        else if (f & (7 << 20))
            mask = 0x100000;
        else if (f & 0x1800000)
            mask = 8 << 20;
        else if (f & 0x1e000000)
            mask = 0x6000000;
        cm_SendSetField(ch->netId, 0x2c, 4, 0, mask);
    }
    return 1;
}
